import{_ as t,o as i,c as r,ak as o}from"./chunks/framework.BLy9NAdO.js";const f=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"introduction/overview.md","filePath":"introduction/overview.md","lastUpdated":1778427181000}'),a={name:"introduction/overview.md"};function n(s,e,c,l,g,d){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h1><p>NBCL is a <strong>configuration language</strong> with <strong>scripting capabilities</strong>. Unlike pure configuration formats like JSON, or TOML, it can produce side effects alongside resolving into data. This makes it especially useful for large configs, defining UI components, or anywhere you need an extensible scripting language that happens to prioritize configuration by default.</p><p>That said, NBCL is not the right tool for every job. It is best when both of its configuration and scripting capabilities are used together. If you <strong>only</strong> need pure scripting, go for a language like <a href="https://crates.io/crates/rhai" target="_blank" rel="noreferrer">rhai</a>, and if you <strong>only</strong> need pure static configuration, go for a language like TOML.</p>',3)])])}const u=t(a,[["render",n]]);export{f as __pageData,u as default};
